<template>
 <div class="market-heatmap" :class="{'hm-dark':dark}">
  <div class="hm-toolbar"><label>方块面积<select v-model="basis" aria-label="热力图面积依据"><option value="cap">美元市值</option><option value="equal">等面积</option></select></label><span id="hm-description">{{layoutBasis==='cap'?`按美元市值分配面积 · ${tiles.length} 个标的`:'等面积显示 · 面积不代表市值'}}<template v-if="basis==='cap'&&layoutBasis==='equal'"> · 当前市值暂缺</template></span><div class="hm-legend"><span :style="{background:heatColor(-8,redUp,dark)}">跌</span><span :style="{background:heatColor(0,redUp,dark)}">平</span><span :style="{background:heatColor(8,redUp,dark)}">涨</span></div></div>
  <div v-if="tradable.length" ref="board" class="hm-board" aria-label="市场行情矩形热力图" aria-describedby="hm-description">
   <button v-for="tile in tiles" :key="tile.item.symbol" type="button" class="hm-tile" :class="labelClass(tile)" :style="tileStyle(tile)" :title="description(tile.item)" :aria-label="description(tile.item)" :aria-pressed="activeSymbol===tile.item.symbol" @mouseenter="activeSymbol=tile.item.symbol" @focus="activeSymbol=tile.item.symbol" @click="activeSymbol=tile.item.symbol">
    <template v-if="tile.width>=32&&tile.height>=28"><span class="hm-symbol"><img v-if="logo(tile.item)" class="hm-logo" :src="logo(tile.item)" :alt="tile.item.ticker" loading="lazy">{{label(tile.item)}}</span><span v-if="tile.width>=115&&tile.height>=88&&tile.item.kind!=='commodity'" class="hm-name">{{tile.item.nameZh||tile.item.name}}</span><span v-if="tile.width>=165&&tile.height>=130&&tile.item.nameEn" class="hm-english">{{tile.item.nameEn}}</span><strong v-if="tile.width>=45&&tile.height>=45" class="hm-percent">{{signed(tile.item.changePercent)}}%</strong></template>
   </button>
  </div>
  <div v-else class="hm-empty">指数以点位显示，不参与市值面积计算。</div>
  <div v-if="missing.length&&layoutBasis==='cap'" class="hm-missing"><span>市值暂缺（不混入面积权重）：</span><button v-for="item in missing" :key="item.symbol" type="button" @click="activeSymbol=item.symbol">{{item.nameZh||item.name}} · {{item.ticker||item.symbol}}</button></div>
  <div v-if="indices.length" class="hm-indices"><span class="hm-section-label">指数点位 · 不参与市值面积</span><button v-for="item in indices" :key="item.symbol" type="button" @click="activeSymbol=item.symbol"><b>{{item.name}}</b><span>{{formatPrice(item)}} 点</span><strong :style="{color:heatColor(item.changePercent,redUp,dark)}">{{signed(item.changePercent)}}%</strong></button></div>
  <aside v-if="activeItem" class="hm-detail" aria-live="polite"><div class="hm-detail-title"><div><h3>{{activeItem.nameZh||activeItem.name}}</h3><span v-if="activeItem.nameEn">{{activeItem.nameEn}} · </span><span>{{activeItem.kind==='commodity'?activeItem.symbol:label(activeItem)}}</span></div><a :href="activeItem.url" target="_blank" rel="noopener noreferrer">查看行情详情 ↗</a></div><div class="hm-metrics"><span>价格 <b>{{formatPrice(activeItem)}} {{activeItem.kind==='index'?'点':activeItem.currency}}</b></span><span>涨跌 <b>{{signed(activeItem.changePercent)}}%</b></span><span v-if="activeItem.kind!=='index'&&activeItem.kind!=='commodity'">美元市值 <b>{{formatCap(activeItem.marketCapUsd)}}</b></span></div><p>行情时间 {{date(activeItem.quoteAt)}}<template v-if="activeItem.marketCapSource"> · 市值来源 {{activeItem.marketCapSource}} · {{activeItem.marketCapQuoteAt?'市值数据':'市值采集'}} {{date(activeItem.marketCapQuoteAt||activeItem.marketCapFetchedAt)}}{{activeItem.marketCapPreserved?'（保留快照）':''}}</template><template v-if="activeItem.marketCapFxAt"> · 汇率日期 {{activeItem.marketCapFxAt}}</template></p></aside>
  <p class="hm-note">悬停、键盘聚焦或点击方块查看详情。颜色按前收价涨跌，非统一的滚动24小时涨跌；市值与价格采集时间可能不同。</p>
 </div>
</template>
<script>
import {marketTreemap,heatColor} from '../utils/market-heatmap.mjs';
export default {
 name:'MarketHeatmap',props:{items:{type:Array,default:()=>[]},redUp:Boolean,dark:Boolean},
 data:()=>({basis:'cap',width:900,height:480,activeSymbol:'',observer:null}),
 computed:{tradable(){return this.items.filter(i=>i.kind!=='index');},indices(){return this.items.filter(i=>i.kind==='index');},weighted(){return this.tradable.filter(i=>Number.isFinite(i.marketCapUsd)&&i.marketCapUsd>0);},missing(){return this.tradable.filter(i=>i.kind!=='commodity'&&(!Number.isFinite(i.marketCapUsd)||i.marketCapUsd<=0));},layoutBasis(){return this.basis==='cap'&&this.weighted.length?'cap':'equal';},tiles(){return marketTreemap(this.tradable,this.width,this.height,this.layoutBasis);},activeItem(){return this.items.find(i=>i.symbol===this.activeSymbol)||this.tiles[0]?.item||this.indices[0];}},
 mounted(){this.measure();if(typeof ResizeObserver!=='undefined'){this.observer=new ResizeObserver(this.measure);if(this.$refs.board)this.observer.observe(this.$refs.board);}window.addEventListener('resize',this.measure);},
 updated(){if(this.observer&&this.$refs.board)this.observer.observe(this.$refs.board);},
 beforeUnmount(){this.observer?.disconnect();window.removeEventListener('resize',this.measure);},
 methods:{heatColor,
  logo(item){return item.kind==='crypto'&&item.ticker?`${process.env.BASE_URL}coin-logos/${item.ticker}.svg`:'';},
  label(item){if(item.kind==='commodity')return String(item.name||'');return item.ticker||item.symbol;},
  measure(){if(!this.$refs.board)return;this.width=this.$refs.board.clientWidth||900;this.height=this.$refs.board.clientHeight||480;},
  signed(n){return `${n>0?'+':''}${Number(n).toFixed(2)}`;},
  formatPrice(item){const n=Math.abs(item.price);const digits=item.kind==='crypto'&&n>0&&n<1?Math.min(12,Math.max(4,2-Math.floor(Math.log10(n)))):2;return Number(item.price).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:digits});},
  formatCap(n){if(!Number.isFinite(n)||n<=0)return '暂无';return '$'+(n>=1e12?(n/1e12).toFixed(2)+' 万亿':n>=1e8?(n/1e8).toFixed(2)+' 亿':n.toLocaleString('zh-CN',{maximumFractionDigits:0}));},
  date(value){const d=new Date(value);return Number.isFinite(d.getTime())?d.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'未知';},
  description(item){return `${item.nameZh||item.name} ${item.nameEn||''} ${item.ticker||item.symbol}，${this.formatPrice(item)} ${item.currency}，涨跌 ${this.signed(item.changePercent)}%，${item.kind==='index'?'指数点位':`美元市值 ${this.formatCap(item.marketCapUsd)}`}`;},
  labelClass(t){return t.width>=150&&t.height>=120?'hm-large':t.width>=75&&t.height>=60?'hm-medium':'hm-small';},
  tileStyle(t){return {left:t.x+'px',top:t.y+'px',width:Math.max(0,t.width-1)+'px',height:Math.max(0,t.height-1)+'px',background:heatColor(t.item.changePercent,this.redUp,this.dark)};}
 }
};
</script>
<style scoped>
.market-heatmap{min-width:0;color:var(--m-text,#26364c)}.hm-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:10px;color:var(--m-muted,#7b8799);font-size:11px}.hm-toolbar label{display:flex;align-items:center;gap:6px}.hm-toolbar select{padding:5px 8px;border:1px solid var(--m-line,#d9e0e6);border-radius:5px;background:transparent;color:var(--m-text,#26364c);font:inherit}.hm-dark select option{background:#181f2d}.hm-legend{display:flex;gap:3px;margin-left:auto}.hm-legend span{padding:3px 11px;border-radius:2px;color:white;font-size:10px}
.hm-board{position:relative;height:480px;min-width:0;overflow:hidden;background:#15251c;border:1px solid var(--m-line,#304d3a);border-radius:8px}.hm-board .hm-tile{position:absolute;box-sizing:border-box;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:4px;overflow:hidden;min-width:0;min-height:0;margin:0;padding:2px;border:0;border-radius:0;cursor:pointer;color:white;font-family:inherit;line-height:1.3;text-align:center;text-shadow:0 1px 3px rgba(0,0,0,.25)}.hm-tile:hover,.hm-tile:focus-visible{z-index:2;box-shadow:inset 0 0 0 2px #f4edd3;outline:0}.hm-symbol{max-width:100%;overflow:hidden;text-overflow:ellipsis;font-size:12px;font-weight:700;white-space:nowrap}.hm-logo{width:12px;height:12px;border-radius:50%;object-fit:contain;background:rgba(255,255,255,.92);vertical-align:-2px;margin-right:4px}.hm-small .hm-logo{width:9px;height:9px;margin-right:3px}.hm-large .hm-logo{width:18px;height:18px;margin-right:6px}.hm-name{max-width:95%;font-size:13px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}.hm-english{max-width:90%;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;opacity:.85}.hm-percent{font-size:15px;font-variant-numeric:tabular-nums}.hm-large .hm-symbol{font-size:20px}.hm-large .hm-percent{font-size:26px}.hm-small .hm-symbol{font-size:9px}.hm-small .hm-percent{font-size:10px}
.hm-missing{display:flex;align-items:center;flex-wrap:wrap;gap:5px;font-size:10px;color:var(--m-muted);margin-top:10px}.hm-missing button{font:inherit;border:1px dashed var(--m-line);padding:4px 7px;border-radius:4px;background:transparent;color:var(--m-text);cursor:pointer}.hm-indices{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:12px}.hm-section-label{flex-basis:100%;font-size:10px;color:var(--m-muted)}.hm-indices button{display:flex;flex-wrap:wrap;align-items:center;gap:7px;background:transparent;color:var(--m-text);border:1px solid var(--m-line);border-radius:6px;padding:8px;cursor:pointer;font:inherit;font-size:11px}.hm-indices b{font-size:11px}.hm-indices span{font-variant-numeric:tabular-nums}.hm-detail{padding:13px 15px;margin-top:12px;border:1px solid var(--m-line);border-radius:8px;min-height:104px;box-sizing:border-box;background:rgba(127,145,171,.035)}.hm-detail-title{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.hm-detail h3{font-size:14px;margin:0 0 4px;overflow-wrap:anywhere}.hm-detail-title span{font-size:11px;color:var(--m-muted)}.hm-detail a{color:var(--m-text);text-decoration:none;font-size:11px;flex-shrink:0}.hm-metrics{display:flex;gap:20px;flex-wrap:wrap;margin-top:10px;font-size:11px}.hm-metrics span{color:var(--m-muted)}.hm-metrics b{color:var(--m-text);font-weight:600}.hm-detail p,.hm-note{font-size:10px;line-height:1.7;color:var(--m-muted);margin:8px 0 0}.hm-note{margin-top:10px}.hm-empty{padding:20px;color:var(--m-muted);font-size:12px}.market-heatmap select:focus-visible,.hm-detail a:focus-visible,.hm-indices button:focus-visible,.hm-missing button:focus-visible{outline:2px solid #43898d;outline-offset:2px}
@media(max-width:700px){.hm-toolbar{gap:8px}.hm-toolbar>span{order:3;flex-basis:100%}.hm-board{height:500px}.hm-detail{padding:11px}.hm-metrics{gap:8px 14px}.hm-detail-title{gap:8px}.hm-large .hm-symbol{font-size:16px}.hm-large .hm-percent{font-size:22px}.hm-indices button{flex:1 1 40%;justify-content:space-between}.hm-detail a{font-size:10px}}
</style>
